"""중3 영어 진단 세트."""
from question_bank.elementary._common import make_question,validate_elementary_questions
L,S="중3","영어";K=[3,3,3,3,4,4,2,2,3,3,1,1,2,4,2];T=[40,40,40,40,40,45,45,40,45,55,55,60,45,55,55]
def q(n,a,s,t,o,c,ad=False):return make_question(f"M3ENG-{n:02d}",L,S,a,s,t,o,c,T[n-1],f"{o[c-1]}가 문법과 문맥에 맞습니다.",f"{s}를 다시 확인할 필요가 있음.",ad)
D=[("시제","현재완료","I ___ him for five years.",["know","knew","have known","am knowing","will know"],3),("문장 구조","수동태·조동사","The report ___ by Friday.",["must finish","must be finishing","must be finished","must finished","is must finish"],3),("관계사","관계부사 where","This is the house ___ I was born.",["who","which","where","what","when"],3),("분사","현재분사 후치수식","The girl ___ a red hat is my sister.",["wear","wore","wearing","is wear","to wore"],3),("5형식·사역","make + 목적어 + 동사원형","The movie made me ___.",["laughed","laughing","to laugh","laugh","laughs"],4),("간접의문문","간접의문문 어순","I wonder ___.",["why did she leave early","why she leave early","why did she left early","why she left early","did she leave why early"],4),("가주어·진주어","It is ... for ... to","It is important for us ___ regularly.",["exercise","to exercise","exercising only","exercised","exercises"],2),("접속사","unless","You will miss the bus unless you hurry. 알맞은 뜻은?",["서두르면 버스를 놓친다.","서두르지 않으면 버스를 놓친다.","버스가 오면 서두르지 않는다.","버스를 놓쳐도 괜찮다.","버스가 없어서 서둘렀다."],2),("가정법","가정법 과거","If I ___ you, I would tell the truth.",["am","was only","were","will be","have been"],3),("읽기 이해","세부 정보","Sora volunteers at an animal shelter every Saturday. Sora는 어디에서 봉사하나요?",["library","school cafeteria","animal shelter","hospital","museum"],3),("읽기 이해","행동 목적 추론","Minho rehearsed his speech many times and checked his slides before class. 해석은?",["발표를 준비했다.","수업을 빠지려 했다.","컴퓨터를 버리려 했다.","친구에게 편지를 썼다.","운동 경기를 준비했다."],1),("읽기 이해","중심 내용","Use public transportation, save electricity, and reduce waste. 공통 주제는?",["환경을 보호하는 행동","새 차를 사는 방법","음식을 요리하는 법","여행 계획 세우기","운동 경기 규칙"],1),("어휘","문맥 어휘","conserve water의 뜻은?",["물을 데우다","물을 아끼다","물을 버리다","물을 사다","물을 얼리다"],2),("다음 단계 진입 탐색","가정법 과거완료 진입","If I had known about the meeting, I ___ you.",["call","will call","called","would have called","am calling"],4,True),("다음 단계 진입 탐색","분사구문 의미 진입","Having finished her homework, Jina went outside. 먼저 일어난 일은?",["밖에 나간 일","숙제를 끝낸 일","친구를 만난 일","저녁을 먹은 일","잠든 일"],2,True)]
Q=[q(i+1,*x)for i,x in enumerate(D)];validate_elementary_questions(Q,K,590,110)
QUESTION_SET={"level":L,"subject":S,"curriculum":"2015 개정 교육과정 중학교 영어 참고","curriculum_year":2026,"test_version":"M3_ENG_2015R_2026_v1.0","core_count":13,"advance_count":2,"display_name":"중3 영어 진단","questions":Q}
